        const step = ts => {
          if (!start) start = ts;
          const pct = Math.min((ts - start) / 1500, 1);
          el.textContent = Math.round((1 - Math.pow(1 - pct, 3)) * to);
          if (pct < 1) requestAnimationFrame(step); else el.textContent = to;
        };
