// ─── AI SCAN BUTTON ───────────────────────────────────────────────────────────
const AI_SCAN_URL = "https://hjkyameroqufaojuerns.supabase.co/functions/v1/ai-document-scan";

// Lightweight PDF page counter — reads raw bytes for the /Pages /Count marker,
// which is the authoritative page count Adobe and most PDF writers embed in the
// document catalog. This is far more reliable than counting /Type/Page occurrences,
// since those can appear inside compressed object streams and give false counts.
// Returns null (unknown) whenever confidence is low — callers should always allow
// the upload through on null rather than guessing.
const countPdfPages = async (file) => {
  try {
    const buf = await file.arrayBuffer();
    const bytes = new Uint8Array(buf);
    let str = "";
    const chunkSize = 65536;
    for (let i = 0; i < bytes.length; i += chunkSize) {
      str += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(i + chunkSize, bytes.length)));
    }
    // Look for every /Count N near a /Type/Pages declaration — take the largest
    // match found (root pages tree count is usually the biggest in the document).
    const matches = [...str.matchAll(/\/Type\s*\/Pages[^>]{0,200}?\/Count\s+(\d+)/g)];
    if (matches.length > 0) {
      const counts = matches.map(m => parseInt(m[1], 10)).filter(n => !isNaN(n) && n > 0);
      if (counts.length > 0) return Math.max(...counts);
    }
    // No reliable marker found (likely a compressed/linearized PDF) — don't guess.
    return null;
  } catch {
    return null;
  }
};

function AIScanButton({ onScanComplete, label="Scan with AI", description, scanType="receipt", planData, onUpgrade, useCamera=false, compact=false, triggerRef, highlighted=false, saveDocument=false, currentUserId }) {
  const [scanning, setScanning]   = useState(false);
  const [error, setError]         = useState("");
  const [success, setSuccess]     = useState(false);
  const fileRef = useRef(null);
  const canScan = planData?.aiScan;

  const handleClick = () => {
    if (!canScan) { if (onUpgrade) onUpgrade(); return; }
    setError(""); setSuccess(false);
    fileRef.current?.click();
  };

  const handleFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    e.target.value = "";

    const isImage = file.type.startsWith("image/") || /\.(heic|heif|jpg|jpeg|png|webp|gif)$/i.test(file.name);
    const isPdf   = file.type === "application/pdf";
    if (!isPdf && !isImage) { setError("Please select an image or PDF."); return; }
    if (file.size > 50 * 1024 * 1024) { setError("File must be under 50MB."); return; }

    // PDF page guard — only blocks when we're CONFIDENT the page count exceeds the limit.
    // Unknown/uncertain counts always pass through; the server-side check is the real backstop.
    if (isPdf) {
      const pageCount = await countPdfPages(file);
      if (pageCount !== null && pageCount > 95) {
        const tip = scanType === "insurance"
          ? "Try uploading just your declarations page instead — usually the first 1–5 pages of your policy packet. It has everything we need (company, coverage amounts, deductible, renewal date) without using up your document storage on boilerplate pages."
          : "Try uploading just the relevant pages instead of the full document — it scans faster and uses less of your document storage.";
        setError(`This PDF has ${pageCount} pages — that's more than we can scan reliably. ${tip}`);
        return;
      }
    }

    setScanning(true); setError("");

    try {
      let base64, mimeType;

      if (isPdf) {
        base64 = await new Promise((res, rej) => {
          const r = new FileReader();
          r.onload  = () => res(r.result.split(",")[1]);
          r.onerror = () => rej(new Error("Failed to read file"));
          r.readAsDataURL(file);
        });
        mimeType = "application/pdf";
      } else {
        // For camera captures: send raw file directly — camera always produces JPEG
        // For library picks of unsupported formats (HEIC): try canvas, fall back to raw
        const isCameraCapture = useCamera;
        const isHeic = /heic|heif/i.test(file.type + file.name);

        if (isCameraCapture || (!isHeic && file.type.match(/^image\/(jpeg|jpg|png|webp|gif)$/))) {
          // Send raw — format is already supported by Claude
          base64 = await new Promise((res, rej) => {
            const r = new FileReader();
            r.onload  = () => res(r.result.split(",")[1]);
            r.onerror = () => rej(new Error("Failed to read file"));
            r.readAsDataURL(file);
          });
          mimeType = file.type || "image/jpeg";
        } else {
          // Try canvas conversion for unsupported formats
          try {
            base64 = await new Promise((resolve, reject) => {
              const img = new Image();
              const objectUrl = URL.createObjectURL(file);
              img.onload = () => {
                const MAX = 1600;
                let { width, height } = img;
                if (width > MAX || height > MAX) {
                  if (width > height) { height = Math.round(height * MAX / width); width = MAX; }
                  else { width = Math.round(width * MAX / height); height = MAX; }
                }
                const canvas = document.createElement("canvas");
                canvas.width = width; canvas.height = height;
                const ctx = canvas.getContext("2d");
                ctx.fillStyle = "#fff";
                ctx.fillRect(0, 0, width, height);
                ctx.drawImage(img, 0, 0, width, height);
                URL.revokeObjectURL(objectUrl);
                canvas.toBlob(blob => {
                  if (!blob) { reject(new Error("Failed to process image")); return; }
                  const r = new FileReader();
                  r.onload  = () => resolve(r.result.split(",")[1]);
                  r.onerror = () => reject(new Error("Failed to read processed image"));
                  r.readAsDataURL(blob);
                }, "image/jpeg", 0.92);
              };
              img.onerror = () => {
                URL.revokeObjectURL(objectUrl);
                reject(new Error("Could not load image"));
              };
              img.src = objectUrl;
            });
            mimeType = "image/jpeg";
          } catch {
            // Canvas failed — send raw as last resort
            base64 = await new Promise((res, rej) => {
              const r = new FileReader();
              r.onload  = () => res(r.result.split(",")[1]);
              r.onerror = () => rej(new Error("Failed to read file"));
              r.readAsDataURL(file);
            });
            mimeType = "image/jpeg"; // tell Claude to treat it as JPEG
          }
        }
      }

      const resp = await fetch(AI_SCAN_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": "Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imhqa3lhbWVyb3F1ZmFvanVlcm5zIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODAwMDkzNTMsImV4cCI6MjA5NTU4NTM1M30.KhBFWGFqiVLtLBF7Y9nK2BjHqaGKR32E7ZOXUL_Rkmk",
        },
        body: JSON.stringify({ fileBase64: base64, mimeType, scanType }),
      });

      const data = await resp.json();
      console.log("[Scan] status:", resp.status, "response:", JSON.stringify(data));
      if (!resp.ok || !data.ok) throw new Error(data.error || "Scan failed");

      console.log("[Scan] fields:", JSON.stringify(data.fields));

      // Save the original document into the shared Documents vault (home_documents)
      // rather than a loose storage file — this makes it visible in the Documents tab
      // automatically, and any module can reference the same row. No duplicate storage.
      let savedDoc = null;
      if (saveDocument && currentUserId) {
        try {
          const ext = mimeType === "application/pdf" ? "pdf" : (file.name.split(".").pop() || "jpg");
          const path = `${currentUserId}/documents/${Date.now()}-scan-${scanType}.${ext}`;
          const { error: upErr } = await supabase.storage
            .from("expense-files")
            .upload(path, file, { upsert: true, contentType: mimeType });
          if (!upErr) {
            const { data: urlData } = supabase.storage.from("expense-files").getPublicUrl(path);
            const docCategory = scanType === "insurance" || scanType === "additional_policy" ? "insurance" : "other";
            const docName = data.fields?.ins_company || data.fields?.company || `Scanned ${scanType.replace("_"," ")}`;
            const { data: docRow, error: docErr } = await supabase
              .from("home_documents")
              .insert([{
                user_id:     currentUserId,
                name:        docName,
                category:    docCategory,
                description: "Saved automatically from a policy scan",
                expiry_date: data.fields?.ins_renewal_date || data.fields?.renewal_date || null,
                file_url:    urlData.publicUrl + "?t=" + Date.now(),
                file_type:   mimeType,
              }])
              .select()
              .single();
            if (!docErr && docRow) savedDoc = docRow;
          }
        } catch {
          // Document save is best-effort — don't block the field-fill flow if storage fails
        }
      }

      onScanComplete(data.fields, savedDoc);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 3000);
    } catch (err) {
      setError(err.message || "Scan failed — please try again");
    }
    setScanning(false);
  };

  const SCAN_ICONS = { receipt:"📸", warranty:"🔖", invoice:"📋", insurance:"🛡️", document:"📄", nameplate:"📷" };
  const icon = SCAN_ICONS[scanType] || "✨";

  if (compact) {
    return (
      <div style={{flex:1,display:"flex",flexDirection:"column",gap:".3rem"}}>
        <input ref={fileRef} type="file"
          accept={useCamera ? "image/*" : "image/*,.pdf"}
          {...(useCamera ? { capture:"environment" } : {})}
          style={{display:"none"}} onChange={handleFile}
        />
        <button ref={triggerRef} type="button" onClick={handleClick} disabled={scanning}
          style={{display:"flex",alignItems:"center",gap:".5rem",padding:".65rem 1rem",borderRadius:12,border:"1.5px solid",
            borderColor: error ? "rgba(192,57,43,.5)" : useCamera ? "rgba(193,97,64,.6)" : "var(--stone)",
            background: error ? "rgba(192,57,43,.15)" : useCamera ? "linear-gradient(135deg,#234A3D,#2E5A4A)" : "var(--white)",
            color: error ? "#C0392B" : useCamera ? "#F4EDDF" : "var(--dark)",
            fontFamily:"'Hanken Grotesk',sans-serif",fontSize:".82rem",fontWeight:600,
            cursor:"pointer",width:"100%",justifyContent:"center",transition:"all .2s",
            animation: highlighted && useCamera && !error ? "scanPulse 1.5s ease-in-out 3" : "none",
          }}>
          <span style={{fontSize:"1.1rem"}}>{scanning?"⏳":error?"⚠":success?"✓":icon}</span>
          <span>{scanning?"Scanning…":error?"Scan failed":success?"Done!":label}</span>
          {!canScan && <span style={{fontSize:".6rem",background:"rgba(255,255,255,.2)",padding:"1px 6px",borderRadius:6,marginLeft:2}}>Plus</span>}
        </button>
        {error && (
          <div style={{fontSize:".7rem",color:"#C0392B",background:"rgba(192,57,43,.08)",border:"1px solid rgba(192,57,43,.2)",borderRadius:8,padding:".4rem .65rem",lineHeight:1.4}}>
            {error} — <button type="button" onClick={()=>setError("")} style={{background:"none",border:"none",color:"#C0392B",cursor:"pointer",textDecoration:"underline",fontSize:".7rem",padding:0}}>dismiss</button>
          </div>
        )}
      </div>
    );
  }

  return (
    <div style={{marginBottom:"1rem"}}>
      <input ref={fileRef} type="file"
        accept={useCamera ? "image/*" : "image/*,.pdf"}
        {...(useCamera ? { capture:"environment" } : {})}
        style={{display:"none"}} onChange={handleFile}
      />
      <button type="button" className="scan-btn scan-btn-bg" onClick={handleClick} disabled={scanning}>
        <div className="scan-btn-inner">
          <div className="scan-btn-icon">
            {scanning ? "⏳" : success ? "✓" : icon}
          </div>
          <div className="scan-btn-text">
            <div className="scan-btn-title">
              {scanning ? "Scanning…" : success ? "Fields filled!" : label}
              {!canScan && <span className="scan-btn-badge">Plus</span>}
            </div>
            <div className="scan-btn-desc">
              {error   ? `⚠ ${error}` :
               success ? "Review the filled fields and save when ready" :
               scanning ? "Reading your document with AI…" :
               (description || "Tap to select a photo or PDF")}
            </div>
          </div>
          {!scanning && !success && <span className="scan-btn-arrow">→</span>}
        </div>
      </button>
    </div>
  );
}

// ─── LIGHTBOX ────────────────────────────────────────────────────────────────
function Lightbox({ src, onClose }) {
  useBodyScrollLock();
  useEffect(() => {
    const handler = e => { if(e.key==="Escape") onClose(); };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [onClose]);
  return (
    <div className="lightbox" onClick={onClose}>
      <button className="lightbox-close" onClick={onClose}>✕</button>
      <img src={src} alt="Receipt" onClick={e=>e.stopPropagation()} />
    </div>
  );
}

// ─── EXPENSE FILE UPLOAD ──────────────────────────────────────────────────────
function ExpenseFileUpload({ userId, expenseId, currentUrl, onUploaded, label="Receipt / Photo", planData, onUpgrade }) {
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState("");

  const maxMB = planData?.maxFileMB ?? 50;

  const handleFile = async (file) => {
    if (!file) return;
    const isImage = file.type.startsWith("image/");
    const isPdf = file.type === "application/pdf";
    if (!isImage && !isPdf) { setError("Please select an image or PDF."); return; }
    if (file.size > maxMB * 1024 * 1024) { setError(`File must be under ${maxMB}MB on your plan.`); return; }
    setError("");

    // Check total file count before uploading
    if (!currentUrl) { // only check when adding new, not replacing
      const limit = await checkFileLimit(userId, planData);
      if (!limit.ok) {
        if (onUpgrade) onUpgrade();
        else setError(`File limit reached (${limit.max} files on ${planData?.label||"Free"}). Upgrade to add more.`);
        return;
      }
    }

    setUploading(true);
    const ext = file.name.split(".").pop();
    const path = `${userId}/expense-${expenseId || Date.now()}.${ext}`;
    const { error: upErr } = await supabase.storage
      .from("expense-files")
      .upload(path, file, { upsert: true, contentType: file.type });

    if (upErr) { setError("Upload failed — " + upErr.message); setUploading(false); return; }

    const { data } = supabase.storage.from("expense-files").getPublicUrl(path);
    onUploaded(data.publicUrl + "?t=" + Date.now());
    setUploading(false);
  };

  const handleRemove = async () => {
    if (!currentUrl) return;
    // Extract path from URL
    const path = currentUrl.split("/expense-files/")[1]?.split("?")[0];
    if (path) await supabase.storage.from("expense-files").remove([path]);
    onUploaded("");
  };

  return (
    <div className="field s2">
      <label>{label}</label>
      {currentUrl ? (
        <div>
          {currentUrl.match(/\.(jpg|jpeg|png|webp|heic)/i) ? (
            <img src={currentUrl} alt="Receipt" style={{width:"100%",maxHeight:140,objectFit:"cover",borderRadius:"var(--r-sm)",marginBottom:"6px"}} />
          ) : (
            <a href={currentUrl} target="_blank" rel="noopener noreferrer" className="exp-file-pdf">
              📄 View PDF receipt
            </a>
          )}
          <button className="btn btn-danger btn-sm" style={{marginTop:"6px"}} onClick={handleRemove}>✕ Remove file</button>
        </div>
      ) : (
        <div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:".5rem"}}>
            <label style={{display:"flex",flexDirection:"column",alignItems:"center",gap:".3rem",border:"1.5px dashed var(--stone)",borderRadius:"var(--r-sm)",padding:".75rem .5rem",cursor:"pointer",background:"var(--white)",transition:"all .15s",WebkitTapHighlightColor:"transparent"}}
              onTouchStart={e=>{e.currentTarget.style.borderColor="var(--rust)";e.currentTarget.style.background="var(--rust-light)";}}
              onTouchEnd={e=>{e.currentTarget.style.borderColor="var(--stone)";e.currentTarget.style.background="var(--white)";}}>
              <span style={{fontSize:"1.3rem"}}>📷</span>
              <span style={{fontSize:".72rem",fontWeight:700,color:"#8A8178"}}>Take photo</span>
              <input type="file" accept="image/*" capture="environment" style={{position:"absolute",width:1,height:1,opacity:0,overflow:"hidden",clip:"rect(0,0,0,0)"}} onChange={e=>handleFile(e.target.files[0])}/>
            </label>
            <label style={{display:"flex",flexDirection:"column",alignItems:"center",gap:".3rem",border:"1.5px dashed var(--stone)",borderRadius:"var(--r-sm)",padding:".75rem .5rem",cursor:"pointer",background:"var(--white)",transition:"all .15s",WebkitTapHighlightColor:"transparent"}}
              onTouchStart={e=>{e.currentTarget.style.borderColor="var(--rust)";e.currentTarget.style.background="var(--rust-light)";}}
              onTouchEnd={e=>{e.currentTarget.style.borderColor="var(--stone)";e.currentTarget.style.background="var(--white)";}}>
              <span style={{fontSize:"1.3rem"}}>📎</span>
              <span style={{fontSize:".72rem",fontWeight:700,color:"#8A8178"}}>Choose file</span>
              <input type="file" accept="image/*,.pdf" style={{position:"absolute",width:1,height:1,opacity:0,overflow:"hidden",clip:"rect(0,0,0,0)"}} onChange={e=>handleFile(e.target.files[0])}/>
            </label>
          </div>
          <div style={{fontSize:".7rem",color:"#A8A09A",textAlign:"center",marginTop:".4rem"}}>JPG, PNG, PDF — up to {maxMB}MB</div>
        </div>
      )}
      {uploading && <div className="exp-upload-progress"><span className="spinner" style={{width:12,height:12,borderWidth:2}}/>Uploading…</div>}
      {error && <div style={{color:"var(--red)",fontSize:".75rem",marginTop:"3px"}}>⚠️ {error}</div>}
    </div>
  );
}

function ExpenseForm({ data, onChange, projects=[], userId, planData, onUpgrade, contractors=[] }) {
  const f = (k,v) => onChange({...data,[k]:v});

  const handleReceiptScan = (fields) => {
    const updates = {};
    if (fields.vendor)        updates.vendor      = fields.vendor;
    if (fields.amount)        updates.amount      = fields.amount;
    if (fields.purchase_date) updates.date        = fields.purchase_date;
    if (fields.description)   updates.description = fields.description;
    if (fields.category)      updates.category    = fields.category;
    if (fields.notes)         updates.notes       = fields.notes;
    if (Object.keys(updates).length > 0) onChange({...data, ...updates});
  };

  return (
    <div>
      {/* Scan leads — camera-first on mobile */}
      <AIScanButton
        onScanComplete={handleReceiptScan}
        label="Scan receipt or invoice"
        description="Photo or PDF — fills vendor, amount, date & category"
        scanType="receipt"
        planData={planData}
        onUpgrade={onUpgrade}
        useCamera={true}
      />
      <div className="scan-divider">or fill in manually</div>
      <div className="fg">
        <div className="field s2"><label>Description *</label><input value={data.description||""} onChange={e=>f("description",e.target.value)} placeholder="e.g. HVAC Service Call" /></div>
        <div className="field"><label>Category</label><select value={data.category||""} onChange={e=>f("category",e.target.value)}><option value="">Select…</option>{CATEGORIES.map(c=><option key={c}>{c}</option>)}</select></div>
        <div className="field"><label>Amount ($)</label><input type="number" value={data.amount||""} onChange={e=>f("amount",e.target.value)} placeholder="0" /></div>
        <div className="field"><label>Date</label><input type="date" value={data.date||""} onChange={e=>f("date",e.target.value)} /></div>
        <div className="field s2"><label>Contractor</label>
          <ContractorPicker value={data.vendor||""} onChange={v=>f("vendor",v)} contractors={contractors} placeholder="Who did the work"/>
        </div>
        {projects.length > 0 && (
          <div className="field s2">
            <label>Link to Project (optional)</label>
            <select value={data.project_id||""} onChange={e=>f("project_id",e.target.value?Number(e.target.value):null)}>
              <option value="">No project</option>
              {projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </div>
        )}
        <div className="field s2"><label>Notes</label><textarea value={data.notes||""} onChange={e=>f("notes",e.target.value)} placeholder="Invoice #, notes…" /></div>
        <ExpenseFileUpload
          userId={userId}
          expenseId={data.id}
          currentUrl={data.file_url||""}
          onUploaded={url=>f("file_url",url)}
          planData={planData}
          onUpgrade={onUpgrade}
        />
      </div>
    </div>
  );
}

